import { useState, useEffect } from "react";
import axios from "axios";
import styles from "./TypeProduct.module.css";
import { NavLink } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCaretDown } from "@fortawesome/free-solid-svg-icons";
import { useRef } from "react";

function TypeProduct() {
  const [data, setData] = useState([]);
  const [showList, setShowList] = useState(false);
  const [showTitle, setShowTitle] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);
  const menuRef = useRef(null);

  // xử lý ẩn hiện loại sp
  useEffect(() => {
    const handleScroll = () => {
      // chỉ áp dụng khi là mobile
      if (window.innerWidth <= 768) {
        const currentScrollY = window.scrollY;
  
        if (currentScrollY > lastScrollY) {
          setShowTitle(false); // cuộn xuống thì ẩn
        } else {
          setShowTitle(true); // cuộn lên thì hiện
        }
  
        setLastScrollY(currentScrollY);
      }
    };
  
    window.addEventListener("scroll", handleScroll);
  
    return () => window.removeEventListener("scroll", handleScroll);
  }, [lastScrollY]);
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setShowList(false);
      }
    };
  
    document.addEventListener("mousedown", handleClickOutside);
  
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);
  //kết thúc xử lý

  useEffect(() => {
    const fetchTypeProducts = async () => {
      try {
        const response = await axios.get("https://sieuthidt.io.vn/typeProduct");
        setData(response.data.typeProducts);
      } catch (error) {
        console.error("Lỗi kết nối server:", error);
      }
    };

    fetchTypeProducts();
  }, []);

  return (
    <div className={styles.wrapper}>
  {/* Overlay chỉ hiện khi mở danh mục */}
  {showList && (
    <div
      className={styles.overlay}
      onClick={() => setShowList(false)}
    ></div>
  )}

  <div className={`${styles.container}`} ref={menuRef}>
    {showTitle && (
      <div className={`${styles.button} text-center`}>
        <button onClick={() => setShowList(!showList)}>
          DANH MỤC SẢN PHẨM
          <FontAwesomeIcon
            className={styles.icon}
            icon={faCaretDown}
            style={{ cursor: "pointer", marginLeft: "8px" }}
          />
        </button>
      </div>
    )}
    <div
      ref={menuRef}
      className={`${styles.containerTypeProduct} ${
        showList ? styles.show : styles.hide
      }`}
    >
      {data.map((element) => (
        <NavLink
          to={`/san-pham/${element.slug}`}
          key={element._id}
          className={`${styles.typeProduct}`}
          onClick={() => setShowList(false)}
        >
          <span>{element.name}</span>
        </NavLink>
      ))}
      <img className={`${styles.imga1}`} width={'100%'} src="https://sieuthidt.io.vn/uploads/web 1-01.png"></img>
    </div>
  </div>
  
</div>
  );
}

export default TypeProduct;
