import styles from "./infotransaction.module.css";
function InfoTransaction() {
    return (
        <div className={styles.containercollectionInfo}>
            <h3 className={styles.titlecollectionInfo}>Thông tin về điều kiện giao dịch chung</h3>
            <p>Chào mừng Quý khách đến với website <strong>sieuthidt.com</strong> – được thiết lập và thuộc sở hữu của CÔNG TY CỔ PHẦN DT FOOD. Khi Quý khách truy cập vào website của chúng tôi đồng nghĩa với việc quý khách đã đồng ý với các điều khoản này.</p>
            <p>Website có thể được thay đổi, chỉnh sửa hoặc điều chỉnh bất kỳ nội dung nào trong Quy định và Điều kiện sử dụng và có hiệu lực sau 5 ngày, khi những thay đổi được thông báo và đăng tải đầy đủ trên website.</p>
            <p>Quý khách vui lòng đọc kỹ Điều khoản và Điều kiện giao dịch này trước khi đặt mua bất kỳ sản phẩm, dịch vụ nào trên <strong>sieuthidt.com</strong>.</p>
            <p className={styles.boldText}>- Các điều kiện hoặc hạn chế trong việc cung cấp hàng hóa hoặc dịch vụ</p>
            <p>Để đảm bảo tính công bằng và quyền lợi của Khách hàng là người tiêu dùng cuối cùng, <strong>sieuthidt.com</strong> có quyền áp dụng các điều kiện hạn chế trong việc triển khai các chương trình khuyến mại: không giới hạn, giới hạn về số lượng sản phẩm tối đa trong mỗi chương trình khuyến mại mà một Khách hàng được mua, giới hạn về mục đích mua sản phẩm (chỉ sử dụng cho tiêu dùng, không được kinh doanh, mua đi bán lại…), hoặc các giới hạn khác (nếu có) được quy định chi tiết trong từng Chương trình khuyến mại. Các điều kiện hạn chế này sau đây được gọi là Chính sách khuyến mại.</p>
            <p>Vì vậy, <strong>sieuthidt.com</strong> có quyền không xác nhận, từ chối, hủy hoặc thu hồi lại các sản phẩm đã giao của các Đơn đặt hàng vi phạm bất kỳ nội dung nào trong Chính sách khuyến mại.</p>
            <p><strong>sieuthidt.com</strong> có quyền không xác nhận, từ chối hoặc hủy, thu hồi các sản phẩm đã giao của các Đơn đặt hàng của Khách hàng trong một số trường hợp khác theo quyết định của yoona.vn mà không cần thông báo đến Khách hàng.</p>
            <p className={styles.boldText}>- Các tiêu chuẩn dịch vụ, quy trình cung cấp dịch vụ, biểu phí và các điều khoản khác liên quan đến việc cung cấp dịch vụ</p>
            <p><strong>Bán hàng thật, không quảng cáo</strong></p>
            <p><strong>sieuthidt.com</strong> là website hỗ trợ người mua có thể sử dụng các sản phẩm của DT chứ không phải là nền tảng để quảng cáo cho các sản phẩm hay gian hàng của các bên người bán khác.</p>
            <p><strong>Tôn trọng lẫn nhau</strong></p>
            <p>Chúng tôi muốn xây dựng một lượng khách hàng an toàn và văn minh để mọi người cùng tận hưởng niềm vui mua sắm trên di động (Không cần phải đến trực tiếp cửa hàng của DT).</p>
            <p><strong>Giữ “lịch sử mua hàng” tốt</strong></p>
            <p>Để nhận được nhiều khuyến mại cho khách hàng thân thiết, đừng quên duy trì sự mua bán thường xuyên, không “bom” hàng, nhận hàng đúng hẹn và giảm thiểu các trường hợp hủy, trả đơn hàng và hoàn tiền không cần thiết.</p>
            <p><strong>Nói không với bán hàng giả, hàng nhái</strong></p>
            <p><strong>sieuthidt.com</strong> cam kết chỉ đăng bán các mặt hàng chính hãng vì việc đăng bán hàng giả, hàng nhái là hành vi vi phạm pháp luật. Trong trường hợp khách hàng có phản hồi lại, DT sẽ có sự tra soát lại và trong trường hợp xác minh phản hồi là đúng thì sẽ có sự bồi thường cho khách hàng, lên bài đính chính và xóa các mặt hàng này ra khỏi hệ thống.</p>
            <p><strong>Các điều khoản khác</strong></p>
            <p>Khi sử dụng website <strong>sieuthidt.com</strong> của DT, Quý khách đã mặc nhiên chấp thuận các điều khoản và điều kiện sử dụng (sau đây gọi tắt là “Điều kiện Sử dụng”) được quy định dưới đây. Để biết được các sửa đổi mới nhất, Quý khách nên thường xuyên kiểm tra lại “Điều kiện Sử dụng”. <strong>sieuthidt.com</strong> có quyền thay đổi, điều chỉnh, thêm hay bớt các nội dung của “Điều kiện Sử dụng” tại bất kỳ thời điểm nào. Nếu Quý khách vẫn tiếp tục sử dụng website sau khi có các thay đổi như vậy thì có nghĩa là Quý khách đã chấp thuận các thay đổi đó.</p>
            <p><strong>Nghĩa vụ của DT</strong></p>
            <p>Thông báo website với Bộ Công Thương website cung cấp dịch vụ thương mại điện tử;</p>
            <p>Xây dựng và công bố trên website những thông tin: Thông tin đơn vị; Hướng dẫn sử dụng website; Thông tin về điều kiện giao dịch chung; Chính sách bảo mật; Thông tin về các phương thức thanh toán; Chính sách giải quyết khiếu nại; Chính sách giao hàng và vận chuyển; …</p>
            <p>Yêu cầu người mua sử dụng website cung cấp tối thiểu các thông tin có liên quan khi đăng ký tài khoản.</p>
            <p>Lưu trữ thông tin đăng ký của các thành viên sử dụng website và thường xuyên cập nhật những thông tin thay đổi, bổ sung có liên quan;</p>
            <p>Ngăn chặn và loại bỏ khỏi website các thông tin thuộc danh mục hàng hóa, dịch vụ cấm kinh doanh theo quy định của pháp luật;</p>
            <p>Loại bỏ khỏi website những thông tin vi phạm quy chế của website/pháp luật khác khi phát hiện hoặc nhận được phản ánh có căn cứ xác thực về những thông tin này;</p>
            <p>Cung cấp thông tin, hỗ trợ cơ quan quản lý nhà nước điều tra các hành vi kinh doanh vi phạm pháp luật sử dụng website của mình;</p>
            <p>Cung cấp thông tin về tình hình kinh doanh của mình khi có yêu cầu của cơ quan nhà nước có thẩm quyền để phục vụ hoạt động thống kê thương mại điện tử, hoạt động thanh tra, kiểm tra và xử lý vi phạm</p>
            <p><strong>Nghĩa vụ của người mua</strong></p>
            <p>Cung cấp đầy đủ và chính xác tối thiểu một trong các thông tin: Họ và tên, Số điện thoại, địa chỉ thì mới đặt hàng trực tuyến được tại website</p>
            <p>Đọc và hiểu rõ quy chế hoạt động, điều khoản, điều kiện sử dụng dịch vụ website.</p>
            <p>Cam kết những thông tin cung cấp cho DT là chính xác và hoàn chỉnh và giữ cho thông tin của mình trên Website <strong>sieuthidt.com</strong> được cập nhật, chính xác và hoàn chỉnh;</p>
            <p>Tự chịu trách nhiệm về nội dung, hình ảnh, thông tin cá nhân và các thông tin khác, cũng như toàn bộ quá trình giao dịch thông qua Website <strong>sieuthidt.com</strong>;</p>
            <p>Hợp tác và cung cấp thông tin cần thiết cho DT để phục vụ việc giải quyết tranh chấp phát sinh;</p>
            <p>Cung cấp thông tin về giao dịch khi có yêu cầu của cơ quan nhà nước có thẩm quyền;</p>
            <p>Cam kết, đồng ý không sử dụng dịch vụ của Website <strong>sieuthidt.com</strong> cho những mục đích bất hợp pháp, không hợp lý, lừa đảo, đe dọa, thăm dò thông tin bất hợp pháp, phá hoại, tạo ra và phát tán vi-rút gây hư hại tới hệ thống, cấu hình, truyền tải thông tin của <strong>sieuthidt.com</strong> hay sử dụng dịch vụ của DT cho mục đích đầu cơ, tạo lệnh đặt dịch vụ giả, lũng đoạn thị trường, bao gồm phục vụ cho việc phán đoán nhu cầu thị trường. Trong trường hợp vi phạm thì thành viên phải chịu trách nhiệm về các hành vi của mình trước Pháp luật;</p>
            <p>Cam kết không thay đổi, chỉnh sửa, sao chép, truyền bá, phân phối, cung cấp và tạo những công cụ tương tự của dịch vụ do DT cung cấp cho một bên thứ ba nếu không được sự đồng ý của Công ty;</p>
            <p>Không được hành động gây mất uy tín của Website <strong>sieuthidt.com</strong> dưới mọi hình thức, bao gồm nhưng không giới hạn, việc gây mất đoàn kết giữa các thành viên bằng cách sử dụng tên đăng ký thứ hai, thông qua một bên thứ ba, hoặc tuyên truyền, phổ biến những thông tin không có lợi cho uy tín của Công ty;</p>
        </div>
    );
}
export default InfoTransaction;