import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import styles from './GiftRedemption.module.css';
import { jwtDecode } from "jwt-decode";
const GiftRedemption = () => {
    const [code, setCode] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [showPopup, setShowPopup] = useState(false);
    const [popupMessage, setPopupMessage] = useState('');
    const [isWin, setIsWin] = useState(true);
    const navigate = useNavigate();
    const location = useLocation();

    useEffect(() => {
        const params = new URLSearchParams(location.search);

        const phoneFromUrl = params.get("sodienthoai");
        const nameFromUrl = params.get("hovaten");

        if (phoneFromUrl) {
            sessionStorage.setItem("phone", phoneFromUrl);
        }

        if (nameFromUrl) {
            sessionStorage.setItem("name", decodeURIComponent(nameFromUrl));
        }

        const phone = sessionStorage.getItem("phone");
        const name = sessionStorage.getItem("name");

        if (!phone || !name) {
            navigate("/dang-nhap-nhan-qua");
        }
    }, [location.search, navigate]);

    const handleRedeem = async (e) => {
        e.preventDefault();
        if (!code) {
            setError('Vui lòng nhập mã đổi quà.');
            return;
        }
        
        setIsLoading(true);
        setError('');
        setPopupMessage('');

        try {
            const phone = sessionStorage.getItem("phone");
            const name = sessionStorage.getItem("name");
            const response = await fetch(`https://chatapi.io.vn/tham-du-giai-thuong?ma=${code}&sodienthoai=${phone}&hovaten=${name}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                
            });
            
            const data = await response.json(); 
            if (data === "mã không hợp lệ") {
                setError("Mã không hợp lệ hoặc đã được sử dụng.");
            } 
            else if (data.includes("may mắn lần sau")) {
                setPopupMessage("Chúc bạn may mắn lần sau!");
                setIsWin(false);
                setShowPopup(true);
                setCode('');
            } 
            else {
                setPopupMessage(data);
                setIsWin(true);
                setShowPopup(true);
                setCode('');
            }
        } catch (err) {
            console.error(err);
            setError('Đã có lỗi xảy ra. Vui lòng thử lại.');
        } finally {
            setIsLoading(false);
        }
    }

    const closePopup = () => {
        setShowPopup(false);
        setPopupMessage('');
    };

    return (
        <div className={styles.container}>
            <div className={styles.card}>
                <h2 className={styles.title}>Đổi Quà Tặng</h2>
                <p className={styles.subtitle}>Nhập mã sự kiện để nhận thưởng ngay!</p>
                
                <form onSubmit={handleRedeem} className={styles.form}>
                    <div className={styles.inputGroup}>
                        <input
                            type='text'
                            placeholder='Nhập mã đổi quà'
                            value={code}
                            onChange={(e) => setCode(e.target.value)}
                            className={styles.input}
                            onFocus={(e) => e.target.placeholder = ''}
                            onBlur={(e) => e.target.placeholder = 'Nhập mã đổi quà'}
                        />
                    </div>
                    
                    {error && <p className={styles.error}>{error}</p>}
                    <p className={styles.notetext}><strong>Lưu ý:</strong> mỗi mã cào chỉ được nhận thưởng một lần!</p>
                    <button type='submit' className={styles.button} disabled={isLoading}>
                        {isLoading ? 'Đang xử lý...' : 'Đổi Quà'}
                    </button>
                </form>
            </div>

            {showPopup && (
                <div className={styles.overlay}>
                    <div className={styles.popup}>
                        <div className={styles.popupHeader}>
                            <div className={isWin ? styles.iconSuccess : styles.iconLuck}>
                                <img
                                    src={isWin ? '/thanh cong icon.png' : '/thanh cong icon.png'}
                                    alt={isWin ? 'Thành công' : 'Thành công'}
                                    className={styles.statusIcon}
                                />
                            </div>
                        </div>
                        
                        <h3 className={styles.popupTitle}>
                            {isWin ? 'ĐỔI MÃ THÀNH CÔNG!' : 'ĐỔI MÃ THÀNH CÔNG!'}
                        </h3>
                        
                        <div className={styles.popupBody}>
                            <p className={styles.messageText}>{popupMessage}</p> 
                        </div>
                        {showPopup && isWin && (
                            <div className={styles.textMessage}>
                                Vui lòng hãy đến cửa hàng gần nhất và đọc số điện thoại để nhận quà!
                            </div>
                        )}
                        <button onClick={closePopup} className={styles.closeBtn}>
                            Xác nhận
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GiftRedemption;
